const cryptoSignalPage="<!doctype html>\n<html><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#05070a\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\"><meta name=\"apple-mobile-web-app-title\" content=\"ULTRON Crypto\">\n<link rel=\"manifest\" href=\"/crypto-manifest.webmanifest\"><title>ULTRON Crypto Signals</title>\n<style>\n:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#05070a;color:#f6f8fb;font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",system-ui,sans-serif;padding:env(safe-area-inset-top) 16px calc(28px + env(safe-area-inset-bottom))}\n.wrap{max-width:720px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;padding:16px 2px 8px}.brand{font-weight:900;letter-spacing:.12em}.live{font-size:12px;border:1px solid #2a343f;border-radius:999px;padding:6px 9px}\n.hero,.card,.install{border:1px solid #1d2630;background:#0c1117;border-radius:22px;padding:18px;margin:12px 0}.hero h1{font-size:30px;margin:0 0 7px}.muted{color:#96a0ad}.grid{display:grid;gap:12px}\n.row{display:flex;justify-content:space-between;gap:12px;align-items:center}.coin{font-size:21px;font-weight:850}.action{font-size:32px;font-weight:950}.BUY{color:#55e58a}.SELL{color:#ff6b74}.HOLD{color:#ffd166}\n.meter{height:9px;background:#1b2530;border-radius:99px;overflow:hidden;margin:12px 0}.fill{height:100%;background:linear-gradient(90deg,#59bfff,#84ffad)}.facts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px}.fact{background:#111923;padding:10px;border-radius:13px}.small{font-size:13px}\n.buttons{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0}button{border:0;border-radius:15px;padding:14px 12px;font-weight:800;background:#eaf2ff;color:#06111e}.secondary{background:#151e28;color:#eaf2ff;border:1px solid #2b3744}.install{display:none}.empty{padding:28px;text-align:center;color:#8f9aa7;border:1px dashed #26313e;border-radius:18px}.foot{font-size:12px;color:#7e8997;line-height:1.5;margin-top:15px}\n</style></head><body><main class=\"wrap\">\n<div class=\"top\"><div class=\"brand\">ULTRON CRYPTO</div><div id=\"live\" class=\"live\">CONNECTING</div></div>\n<section class=\"hero\"><h1>Live BUY / SELL Signals</h1><div class=\"muted\">BTC and ETH signals from ULTRON's live research engine. Signals are research, not guaranteed returns. Real-money orders still require your approval.</div></section>\n<div id=\"install\" class=\"install\"><b>Add ULTRON to this iPhone</b><br><span class=\"muted\">Open in Safari, tap Share, then Add to Home Screen.</span></div>\n<div class=\"buttons\"><button id=\"alerts\">Enable alerts</button><button class=\"secondary\" id=\"refresh\">Refresh now</button></div>\n<div id=\"cards\" class=\"grid\"><div class=\"empty\">Loading ULTRON signals…</div></div>\n<div class=\"foot\"><span id=\"updated\">Waiting for first update…</span><br>Refreshes every 20 seconds while open. ChatGPT monitoring can alert you when this dashboard is closed.</div>\n</main><script>\nconst cards=document.getElementById('cards'),updated=document.getElementById('updated'),live=document.getElementById('live');\nconst ios=/iPhone|iPad|iPod/i.test(navigator.userAgent),standalone=navigator.standalone===true||matchMedia('(display-mode: standalone)').matches;\nif(ios&&!standalone)document.getElementById('install').style.display='block';let previous={};\nconst pct=n=>Math.round(Number(n||0)*100),money=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2});\nfunction action(x){if(!x||!['BULLISH','BEARISH'].includes(x.direction)||Number(x.score)<.65)return'HOLD';return x.direction==='BULLISH'?'BUY':'SELL'}\nfunction notify(x,a){if(!('Notification'in window)||Notification.permission!=='granted'||a==='HOLD'||previous[x.instrument]===a)return;new Notification('ULTRON '+a+' signal',{body:x.instrument+' · '+pct(x.score)+'% confidence · USD '+money(x.lastPrice)})}\nasync function load(){try{const r=await fetch('/api/crypto-signals',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json(),ranked=Array.isArray(d.ranked)?d.ranked:[];live.textContent='LIVE';live.style.color='#55e58a';cards.innerHTML='';if(!ranked.length)cards.innerHTML='<div class=\"empty\">ULTRON is scanning. No signal is available yet.</div>';for(const x of ranked){const a=action(x);notify(x,a);previous[x.instrument]=a;const el=document.createElement('section');el.className='card';el.innerHTML='<div class=\"row\"><div><div class=\"coin\">'+x.instrument+'</div><div class=\"muted small\">'+(x.regime||'unknown')+' regime</div></div><div class=\"action '+a+'\">'+a+'</div></div><div class=\"meter\"><div class=\"fill\" style=\"width:'+Math.min(100,pct(x.score))+'%\"></div></div><div class=\"row\"><b>'+pct(x.score)+'% confidence</b><b>USD '+money(x.lastPrice)+'</b></div><div class=\"facts\"><div class=\"fact\"><span class=\"muted small\">Signal</span><br><b>'+(x.direction||'NEUTRAL')+'</b></div><div class=\"fact\"><span class=\"muted small\">Confidence</span><br><b>'+pct(x.score)+'%</b></div><div class=\"fact\"><span class=\"muted small\">Regime</span><br><b>'+(x.regime||'unknown')+'</b></div><div class=\"fact\"><span class=\"muted small\">Action</span><br><b>'+a+'</b></div></div><p class=\"small muted\">'+(x.rationale||'')+'</p>';cards.appendChild(el)}updated.textContent='Last ULTRON cycle: '+(d.lastCycleAt?new Date(d.lastCycleAt).toLocaleString():'not available')}catch(e){live.textContent='RETRYING';live.style.color='#ffd166';updated.textContent='Refresh error: '+e.message}}\ndocument.getElementById('refresh').onclick=load;document.getElementById('alerts').onclick=async()=>{if(!('Notification'in window)){alert('Install this dashboard to your Home Screen for iPhone notifications, or use ChatGPT monitoring.');return}const p=await Notification.requestPermission();document.getElementById('alerts').textContent=p==='granted'?'Alerts enabled':'Alerts not enabled'};\nif('serviceWorker'in navigator)navigator.serviceWorker.register('/crypto-sw.js').catch(()=>{});load();setInterval(load,20000);\n</script></body></html>";
